function findLongestWord(sentenceString) {
  const wordsArray = sentenceString.split(' ');
  let longestWordSoFar = '';
  let maxLengthFound = 0;
  let wordCount = wordsArray.length;
  let hasSpecialChars = false; // Example of a boolean variable

  for (let i = 0; i < wordCount; i++) {
    let currentWord = wordsArray[i];
    let cleanedWord = currentWord.replace(/[^a-zA-Z0-9]/g, ''); // Remove punctuation
    let currentLength = cleanedWord.length;

    if (currentLength > maxLengthFound) {
      maxLengthFound = currentLength;
      longestWordSoFar = cleanedWord;
      hasSpecialChars = currentWord !== cleanedWord; // Update boolean if word was cleaned
    }
  }
  return longestWordSoFar;
}

