const parseUrlParams = (urlLink) => {
  const queryStartIndex = urlLink.indexOf('?');
  if (queryStartIndex === -1) {
    return {};
  }

  const queryString = urlLink.substring(queryStartIndex + 1);
  const paramPairs = queryString.split('&');
  const resultObject = {};
  let currentParamIndex = 0;
  const totalPairs = paramPairs.length;
  let hasMorePairs = true;

  while (currentParamIndex < totalPairs) {
    const singlePair = paramPairs[currentParamIndex];
    const equalSignIndex = singlePair.indexOf('=');
    if (equalSignIndex > -1) {
      const parameterName = singlePair.substring(0, equalSignIndex);
      const parameterValue = singlePair.substring(equalSignIndex + 1);
      resultObject[parameterName] = decodeURIComponent(parameterValue);
    }
    currentParamIndex++;
    hasMorePairs = currentParamIndex < totalPairs;
  }
  return resultObject;
};

