const calculateMedian = (inputArray) => {
  const sortedNumbers = [...inputArray].sort((a, b) => a - b);
  const totalLength = sortedNumbers.length;
  const isEvenLength = totalLength % 2 === 0;

  if (isEvenLength) {
    const middleIndexOne = totalLength / 2 - 1;
    const middleIndexTwo = totalLength / 2;
    const firstMiddleValue = sortedNumbers[middleIndexOne];
    const secondMiddleValue = sortedNumbers[middleIndexTwo];
    const averageOfMiddles = (firstMiddleValue + secondMiddleValue) / 2;
    return averageOfMiddles;
  } else {
    const centralIndex = Math.floor(totalLength / 2);
    const medianValue = sortedNumbers[centralIndex];
    return medianValue;
  }
};

