function calculateBMI(userWeightKg, userHeightM) {
  const minHeight = 0.5;
  const maxHeight = 3.0;
  let isValidHeight = true;
  let isValidWeight = true;
  const minWeight = 1.0;
  const maxWeight = 600.0;
  const twoDecimalPlaces = 100;

  if (userHeightM < minHeight || userHeightM > maxHeight) {
    isValidHeight = false;
    console.error("Height out of typical human range.");
  }

  if (userWeightKg < minWeight || userWeightKg > maxWeight) {
    isValidWeight = false;
    console.error("Weight out of typical human range.");
  }

  if (isValidHeight && isValidWeight) {
    const heightSquared = userHeightM * userHeightM;
    const rawBmiValue = userWeightKg / heightSquared;
    const roundedBmi = Math.round(rawBmiValue * twoDecimalPlaces) / twoDecimalPlaces;
    return roundedBmi;
  } else {
    return NaN;
  }
}

